package io.knowledgebrain.media;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.media.v1.*;
import com.google.protobuf.ByteString;
final class MediaStore {
 record Info(UUID mediaId,UUID spaceId,String state,long version,String filename,String mimeType,long byteSize,String sha256,Instant createdAt,Instant completedAt){}
 record Stored(Info info,String objectVersion){}
 record Page(List<Info> items,UUID nextAfter){}
 private final JdbcTemplate jdbc;private final TransactionTemplate transaction;private final Clock clock;private final UuidV7 ids;
 MediaStore(DataSource source,Clock clock){jdbc=new JdbcTemplate(source);transaction=new TransactionTemplate(new DataSourceTransactionManager(source));transaction.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 static void id(UUID id){if(id==null || id.version()!=7 || id.variant()!=2)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"UUIDv7 required");}
 private void lock(UUID space){jdbc.queryForObject("SELECT pg_advisory_xact_lock(?)",Object.class,space.getMostSignificantBits()^space.getLeastSignificantBits());}
 Info create(UUID space,UUID actor,MediaInput.Upload value,String trace){id(space);id(actor);var input=MediaInput.validate(value);return transaction.execute(status->{lock(space);long allocated=jdbc.queryForObject("SELECT coalesce(sum(byte_size),0) FROM media WHERE space_id=?",Long.class,space);int pending=jdbc.queryForObject("SELECT count(*) FROM media WHERE space_id=? AND state='PENDING'",Integer.class,space);if(allocated+input.byteSize()>MediaInput.SPACE_QUOTA || pending>=10)throw new ResponseStatusException(HttpStatus.CONFLICT,"Media allocation quota reached");UUID id=ids.next();jdbc.update("INSERT INTO media(media_id,space_id,actor_id,state,version,filename,mime_type,byte_size,sha256,created_at) VALUES (?,?,?,'PENDING',1,?,?,?,?,?)",id,space,actor,input.filename(),input.mimeType(),input.byteSize(),input.sha256(),Timestamp.from(clock.instant()));var row=get(space,id);event(row,actor,trace,"MediaUploadRequested");return row;});}
 Stored stored(UUID space,UUID media){id(space);id(media);var rows=jdbc.query("SELECT * FROM media WHERE space_id=? AND media_id=?",(rs,n)->new Stored(new Info(rs.getObject("media_id",UUID.class),rs.getObject("space_id",UUID.class),rs.getString("state"),rs.getLong("version"),rs.getString("filename"),rs.getString("mime_type"),rs.getLong("byte_size"),rs.getString("sha256"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("completed_at")==null?null:rs.getTimestamp("completed_at").toInstant()),rs.getString("object_version")),space,media);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Media unavailable");return rows.getFirst();}
 Info get(UUID space,UUID media){return stored(space,media).info();}
 Info available(UUID space,UUID media){var value=get(space,media);if(!"AVAILABLE".equals(value.state()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Upload is not complete");return value;}
 Info complete(UUID space,UUID media,UUID actor,String objectVersion,String trace){id(actor);if(objectVersion==null || objectVersion.isBlank() || objectVersion.equals("null"))throw new IllegalArgumentException("Immutable object version required");return transaction.execute(status->{lock(space);var prior=get(space,media);if("AVAILABLE".equals(prior.state()))return prior;jdbc.update("UPDATE media SET state='AVAILABLE',version=version+1,object_version=?,completed_at=? WHERE space_id=? AND media_id=?",objectVersion,Timestamp.from(clock.instant()),space,media);var current=get(space,media);event(current,actor,trace,"MediaUploaded");return current;});}
 Page list(UUID space,UUID after,int limit){id(space);if(after!=null)id(after);if(limit<1 || limit>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid Media page limit");var args=new ArrayList<Object>();args.add(space);String sql="SELECT media_id FROM media WHERE space_id=?";if(after!=null){sql+=" AND media_id>?";args.add(after);}sql+=" ORDER BY media_id LIMIT ?";args.add(limit+1);var rows=jdbc.queryForList(sql,UUID.class,args.toArray());var page=rows.subList(0,Math.min(limit,rows.size())).stream().map(id->get(space,id)).toList();return new Page(page,rows.size()>limit?page.getLast().mediaId():null);}
 private void event(Info value,UUID actor,String trace,String type){if(trace==null || !trace.matches("[0-9a-f]{32}") || trace.equals("0".repeat(32)))throw new IllegalArgumentException("Valid trace required");UUID event=ids.next();Instant now=clock.instant();var payload=MediaChangedPayloadV1.newBuilder().setMediaId(value.mediaId().toString()).setVersion(value.version()).setState(value.state()).setFilename(value.filename()).setMimeType(value.mimeType()).setByteSize(value.byteSize()).setSha256(value.sha256()).setVisibility("PRIVATE").build();var envelope=MediaEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("media-service").setAggregateType("Media").setAggregateId(value.mediaId().toString()).setSpaceId(value.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(ByteString.copyFrom(payload.toByteArray())).build();jdbc.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,'file',?,?,?,?,'media','file-events','1',?)",event,value.mediaId(),type,Timestamp.from(now),trace,envelope.toByteArray());}
}
